'''Python3 implementation of tree using array
numbering starting from 0 to n-1.'''

tree = [None] * 10

'''create root'''

def root(key):
    if tree[0] != None:
        print("Tree already had root")
    else:
        tree[0] = key

'''create left son of root'''

def set_left(key, parent):
    if tree[parent] == None:
        print("Can't set child at", (parent * 2) + 1, ", no parent found")
    else:
        tree[(parent * 2) + 1] = key

'''create right son of root'''

def set_right(key, parent):
    if tree[parent] == None:
        print("Can't set child at", (parent * 2) + 2, ", no parent found")
    else:
        tree[(parent * 2) + 2] = key

'''Print tree'''

def print_tree():
    for i in range(10):
        if tree[i] != None:
            print(tree[i], end="")
        else:
            print("-", end="")
    print()

'''Driver Code'''

root('A')
set_right('C', 0)
set_left('D', 1)
set_right('E', 1)
set_right('F', 2)
print_tree()

'''Python3 program to count 
number of ways to color
a N node skewed tree with
k colors such that parent
and children have different
colors.'''

'''fast_way is recursive
method to calculate power'''

def fastPow(N, K):
    if (K == 0):
        return 1;
    temp = fastPow(N, int(K / 2));
    if (K % 2 == 0):
        return temp * temp;
    else:
        return N * temp * temp;
def countWays(N, K):
    return K * fastPow(K - 1, N - 1);

'''Driver Code'''

N = 3;
K = 3;
print(countWays(N, K));

'''Returns the min value in a binary tree'''

def find_min_in_BT(root):
    if root is None:
        return float('inf')
    res = root.data
    lres = find_min_in_BT(root.leftChild)
    rres = find_min_in_BT(root.rightChild)
    if lres < res:
        res = lres
    if rres < res:
        res = rres
    return res

'''Naive implementation of find'''

def find(parent, i):
    if (parent[i] == -1):
        return i
    return find(parent, parent[i])

'''Naive implementation of union()'''

def Union(parent, x, y):
    xset = find(parent, x)
    yset = find(parent, y)
    parent[xset] = yset

