'''method can be used to avoid
Global variable frequency'''

'''    Counts the no. of occurrences of a node
(search_for) in a linked list (head)'''
def count(self, temp, key):
    if temp is None:
        return 0
    if temp.data == key:
        return 1 + count(temp.next, key)
    return count(temp.next, key)

def fun1(head):
    if(head == None):
        return
    fun1(head.next)
    print(head.data, end = " ")

def fun2(head):
    if(head == None):
        return
    print(head.data, end = " ")
    if(head.next != None ):
        fun2(head.next.next)
    print(head.data, end = " ")

'''Check if each internal
node of BST has only one child'''

def hasOnlyOneChild (pre, size):
    nextDiff=0; lastDiff=0
    for i in range(size-1):
        nextDiff = pre[i] - pre[i+1]
        lastDiff = pre[i] - pre[size-1]
        if nextDiff*lastDiff < 0:
            return False
    return True

'''driver program to
test above function'''

