'''Python3 program to find
minimum element in a sorted
and rotated array contating
duplicate elements.'''

'''Function to find minimum element'''

def findMin(arr, low, high):
    while (low < high):
        mid = low + (high - low) // 2;
        if (arr[mid] == arr[high]):
            high -= 1;
        elif (arr[mid] > arr[high]):
            low = mid + 1;
        else:
            high = mid;
    return arr[high];

