def arrayEvenAndOdd(arr,  n):
    ind = 0;
    a = [0 for i in range(n)]
    for i in range(n):
        if (arr[i] % 2 == 0):
            a[ind] = arr[i]
            ind += 1
    for i in range(n):
        if (arr[i] % 2 != 0):
            a[ind] = arr[i]
            ind += 1
