'''A Naive recursive implementation of MCP(Minimum Cost Path) problem'''

R = 3
C = 3
import sys

'''A utility function that returns minimum of 3 integers */'''

def min(x, y, z):
    if (x < y):
        return x if (x < z) else z
    else:
        return y if (y < z) else z

'''Returns cost of minimum cost path from (0,0) to (m, n) in mat[R][C]'''

def minCost(cost, m, n):
    if (n < 0 or m < 0):
        return sys.maxsize
    elif (m == 0 and n == 0):
        return cost[m][n]
    else:
        return cost[m][n] + min( minCost(cost, m-1, n-1),
                                minCost(cost, m-1, n),
                                minCost(cost, m, n-1) )

'''Driver program to test above functions'''

cost= [ [1, 2, 3],
        [4, 8, 2],
        [1, 5, 3] ]
print(minCost(cost, 2, 2))

'''Python code for implementation of Naive Recursive
approach'''

def isPalindrome(x):
    return x == x[::-1]
def minPalPartion(string, i, j):
    if i >= j or isPalindrome(string[i:j + 1]):
        return 0
    ans = float('inf')
    for k in range(i, j):
        count = (
            1 + minPalPartion(string, i, k)
            + minPalPartion(string, k + 1, j)
        )
        ans = min(ans, count)
    return ans

'''Driver code'''

def main():
    string = "ababbbabbababa"
    print(
     "Min cuts needed for Palindrome Partitioning is ",
     minPalPartion(string, 0, len(string) - 1),
    )
if __name__ == "__main__":
    main()

'''minCut function'''

def minCut(a):
    cut = [0 for i in range(len(a))]
    palindrome = [[False for i in range(len(a))] for j in range(len(a))]
    for i in range(len(a)):
        minCut = i;
        for j in range(i + 1):
            if (a[i] == a[j] and (i - j < 2 or palindrome[j + 1][i - 1])):      
                palindrome[j][i] = True;
                minCut = min(minCut,0 if  j == 0 else (cut[j - 1] + 1));
        cut[i] = minCut;  
    return cut[len(a) - 1];

'''Driver code'''

if __name__=='__main__':
    print(minCut("aab"))
    print(minCut("aabababaxx"))

'''A Naive recursive python program to find
length of the shortest supersequence'''

def superSeq(X, Y, m, n):
    if (not m):
        return n
    if (not n):
        return m
    if (X[m - 1] == Y[n - 1]):
        return 1 + superSeq(X, Y, m - 1, n - 1)
    return 1 + min(superSeq(X, Y, m - 1, n),
                   superSeq(X, Y, m, n - 1))

'''Driver Code'''

X = "AGGTAB"
Y = "GXTXAYB"
print("Length of the shortest supersequence is %d"
      % superSeq(X, Y, len(X), len(Y)))

'''Function to calculate x raised to the power y in O(logn)'''

def power(x,y):
    temp = 0
    if( y == 0):
        return 1
    temp = power(x, int(y / 2))
    if (y % 2 == 0):
        return temp * temp;
    else:
        return x * temp * temp;

'''A recursive function to get x*y *'''

def multiply(x, y):
    if (y):
        return (x + multiply(x, y-1));
    else:
        return 0;

def pow(a,b):
    if(b):
        return multiply(a, pow(a, b-1));
    else:
        return 1;

