def getSetBitsFromOneToN(N):
    two = 2
    ans = 0
    n = N
    while(n != 0):
        ans += int(N / two) * (two >> 1)
        if((N & (two - 1)) > (two >> 1) - 1):
            ans += (N&(two - 1)) - (two >> 1) + 1
        two <<= 1;
        n >>= 1;
    return ans

def Add(x, y):
    if (y == 0):
        return x
    else:
        return Add( x ^ y, (x & y) << 1)

def changeToZero(a):
    a[ a[1] ] = a[ not a[1] ]
    return a

