'''Efficient Python3 program to
find smallest greater element
in whole array for every element'''

def smallestGreater(arr, n):

    s = set()

    for i in range(n):
        s.add(arr[i])

    newAr = []

    for p in s:
        newAr.append(p)

    for i in range(n):
        temp = lowerBound(newAr, 0, len(newAr),
                          arr[i])

        if (temp < n):
            print(newAr[temp], end = " ")
        else:
            print("_ ", end = "")

'''lowerbound function'''

def lowerBound(vec, low, high, element):

    array = [0] * (len(vec))

    k = 0

    for val in vec:
        array[k] = val
        k += 1
    while (low < high):
        middle = low + int((high - low) / 2)

        if (element > array[middle]):
            low = middle + 1
        else:
            high = middle

    return low + 1

'''Driver code'''

if __name__ == '__main__':

    ar = [ 6, 3, 9, 8, 10, 2, 1, 15, 7 ]
    n = len(ar)

    smallestGreater(ar, n)

def minswaps(arr):
    count = 0
    num_unplaced_zeros = 0

    for index in range(len(arr)-1, -1, -1):
        if arr[index] == 0:
            num_unplaced_zeros += 1
        else:
            count += num_unplaced_zeros
    return count

'''Driver Code'''


