def printTwoElements( arr, size):
    for i in range(size):
        if arr[abs(arr[i])-1] > 0:
            arr[abs(arr[i])-1] = -arr[abs(arr[i])-1]
        else:
            print("The repeating element is", abs(arr[i]))

    for i in range(size):
        if arr[i]>0:
            print("and the missing element is", i + 1)

'''Driver program to test above function */'''

arr = [7, 3, 4, 5, 5, 6, 2]
n = len(arr)
printTwoElements(arr, n)

'''Python3 program to find the
repeating and missing elements
using Maps'''

def main():

    arr = [ 4, 3, 6, 2, 1, 1 ]

    numberMap = {}

    max = len(arr)
    for i in arr:
        if not i in numberMap:
            numberMap[i] = True

        else:
            print("Repeating =", i)

    for i in range(1, max + 1):
        if not i in numberMap:
            print("Missing =", i)
main()

'''Python3 program to find minimum
(or maximum) element
in an array.'''

def getMin(arr,n):
    return min(arr)

def getMax(arr,n):
    return max(arr)

'''Driver Code'''

if __name__=='__main__':
    arr = [12,1234,45,67,1]
    n = len(arr)
    print("Minimum element of array: "
          ,getMin(arr, n))
    print("Maximum element of array: "
          ,getMax(arr, n))

def flattenList2(head):

    headcop = head
    save = []
    save.append(head)
    prev = None

    while (len(save) != 0):
        temp = save[-1]
        save.pop()

        if (temp.next):
            save.append(temp.next)
        if (temp.down):
            save.append(temp.down)

        if (prev != None):
            prev.next = temp

        prev = temp

    return headcop
